  .monday-topbar { height: 52px; display: flex; align-items: center; gap: 14px; padding: 0 18px; background: var(--bg-base); border-bottom: 1px solid var(--border-default); }
  .monday-mark { display: flex; align-items: flex-end; gap: 3px; width: 34px; height: 25px; flex: 0 0 auto; }
