  .monday-mark i:nth-child(1) { height: 20px; background: #F62B54; }
  .monday-mark i:nth-child(2) { height: 16px; margin-bottom: 1px; background: #FFCB00; }
  .monday-mark i:nth-child(3) { height: 12px; margin-bottom: 2px; background: #00C875; }
  .monday-mark i:nth-child(4) { width: 6px; height: 6px; margin: 0 0 2px 2px; background: #579BFC; }
  .monday-wordmark { font-size: 15px; font-weight: 700; letter-spacing: -0.02em; }
  .global-search { width: min(340px, 32vw); height: 32px; margin-left: 18px; display: flex; align-items: center; gap: 8px; padding: 0 11px; color: var(--text-tertiary); background: var(--bg-subtle); border: 1px solid var(--border-subtle); border-radius: var(--radius-md); font-size: 12px; }
  .global-search svg, .nav-icon svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.8; }
