  .side-link span:first-child { width: 18px; text-align: center; color: var(--text-tertiary); }
  .side-link.active { color: var(--color-primary-700); background: var(--color-primary-50); font-weight: 600; }
  .side-link .count { margin-left: auto; min-width: 20px; height: 18px; display: grid; place-items: center; border-radius: var(--radius-full); background: var(--bg-elevated); color: var(--text-tertiary); font-size: 10px; }
  .monday-main { min-width: 0; padding: 28px 32px 36px; overflow: hidden; }
  .board-hero { display: flex; align-items: flex-end; justify-content: space-between; gap: 24px; }
